-- Target table columns (I3). Single SELECT, read-only: run with Ctrl+Enter in DBeaver, then export the result as CSV (with header).
-- Tables the job writes to (from the Blendata export): TB_STAGING_SS_ESIM_CHECKPOINT, TB_STAGING_SS_ESIM_CHECKPOINT_TEMP, TB_STAGING_SS_ESIM_LANDING_TO_DISCOVERY_WORKFLOW_STATUS, TB_STAGING_SS_ESIM_LANDING_TO_DISCOVERY_WORKFLOW_STATUS_TEMP, TB_STAGING_SS_ESIM_RAW_TEMP, TB_TRANSACTION_SS_ESIM_REJECT, TB_TRANSACTION_SS_ESIM_TEMP, TB_TRANSACTION_SS_ESIM_VALID
-- Tables the job only reads (optional, add to the IN list if you want their types too): EXT_DSS_CHECKPOINT_TB_TRANSACTION_SS_ESIM_VALID, EXT_DSS_TB_MASTER_CDR_TYPE, EXT_DSS_VW_SERVICE_MAPPING_BNO_KEY, TB_LANDING_SS_ESIM
SELECT owner, table_name, column_id, column_name, data_type, data_length,
       data_precision, data_scale, nullable, data_default
FROM   all_tab_columns
WHERE  table_name IN ('TB_STAGING_SS_ESIM_CHECKPOINT', 'TB_STAGING_SS_ESIM_CHECKPOINT_TEMP', 'TB_STAGING_SS_ESIM_LANDING_TO_DISCOVERY_WORKFLOW_STATUS', 'TB_STAGING_SS_ESIM_LANDING_TO_DISCOVERY_WORKFLOW_STATUS_TEMP', 'TB_STAGING_SS_ESIM_RAW_TEMP', 'TB_TRANSACTION_SS_ESIM_REJECT', 'TB_TRANSACTION_SS_ESIM_TEMP', 'TB_TRANSACTION_SS_ESIM_VALID')
ORDER  BY table_name, owner, column_id
